{
  "translations": {
    "L0001": "El corrector puso dos encabezados uno junto al otro.",
    "L0002": "En uno escribió «Carta».",
    "L0003": "En el otro escribió «我在等你» («Te estoy esperando»).",
    "L0004": "No son traducciones entre sí, sino citas independientes.",
    "L0005": "No borró el «OK» del margen.",
    "L0006": "Ninguna de las dos cartas ha llegado todavía."
  },
  "sourceNotes": []
}
